import { topicIdsForChapter } from './coverage';
import { GAME_BIBLE_DECISION_COVERAGE } from './traceability';
import {
  defineGameBibleChapter,
  type GameBibleChapter,
  type GameBibleChapterDraft,
} from './types';
import { GAME_BIBLE_SHARED_RULES as rules } from './sharedRules';

const source = (name: string) => `memory-bank/01 MVP/${name}.md`;

const chapterTopics = (chapterId: string): [string[], string[], string[], string[], string[]] => {
  const result: [string[], string[], string[], string[], string[]] = [[], [], [], [], []];
  topicIdsForChapter(chapterId).forEach((topicId, index) => result[index % result.length].push(topicId));
  return result;
};

const chapterDecisions = (chapterId: string): string[] =>
  Object.entries(GAME_BIBLE_DECISION_COVERAGE)
    .filter(([, sectionIds]) => sectionIds.some((sectionId) => sectionId.startsWith(`${chapterId}.`)))
    .map(([decisionId]) => decisionId);

const chapter = (
  draft: Omit<GameBibleChapterDraft, 'topicIdsBySection' | 'decisionRefs'>
): GameBibleChapter => defineGameBibleChapter({
  ...draft,
  topicIdsBySection: chapterTopics(draft.id),
  decisionRefs: chapterDecisions(draft.id),
});

